pragma solidity =0.8.21; interface IERC20 { event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address to, uint256 value) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 value) external returns (bool); function transferFrom(address from, address to, uint256 value) external returns (bool); function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); function mint(address user, uint256 value) external; function burn(address user, uint256 value) external; } contract Auth { mapping(address => uint256) public wards; event Rely(address indexed user); event Deny(address indexed user); function rely(address user) external auth { wards[user] = 1; emit Rely(user); } function deny(address user) external auth { wards[user] = 0; emit Deny(user); } modifier auth() { require(wards[msg.sender] == 1, "Auth/not-authorized"); _; } } library MathLib { enum Rounding { Down, Up, Zero } function mulDiv(uint256 x, uint256 y, uint256 denominator) internal pure returns (uint256 result) { unchecked { uint256 prod0; uint256 prod1; assembly { let mm := mulmod(x, y, not(0)) prod0 := mul(x, y) prod1 := sub(sub(mm, prod0), lt(mm, prod0)) } if (prod1 == 0) { return prod0 / denominator; } require(denominator > prod1); uint256 remainder; assembly { remainder := mulmod(x, y, denominator) prod1 := sub(prod1, gt(remainder, prod0)) prod0 := sub(prod0, remainder) } uint256 twos = denominator & (~denominator + 1); assembly { denominator := div(denominator, twos) prod0 := div(prod0, twos) twos := add(div(sub(0, twos), twos), 1) } prod0 |= prod1 * twos; uint256 inverse = (3 * denominator) ^ 2; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; inverse *= 2 - denominator * inverse; result = prod0 * inverse; return result; } } function mulDiv(uint256 x, uint256 y, uint256 denominator, Rounding rounding) internal pure returns (uint256) { uint256 result = mulDiv(x, y, denominator); if (rounding == Rounding.Up && mulmod(x, y, denominator) > 0) { result += 1; } return result; } function max(uint256 a, uint256 b) internal pure returns (uint256) { return a > b ? a : b; } } library SafeTransferLib { function safeTransferFrom(address token, address from, address to, uint256 value) internal { (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, value)); require(success && (data.length == 0 || abi.decode(data, (bool))), "SafeTransferLib/safe-transfer-from-failed"); } function safeTransfer(address token, address to, uint256 value) internal { (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.transfer.selector, to, value)); require(success && (data.length == 0 || abi.decode(data, (bool))), "SafeTransferLib/safe-transfer-failed"); } function safeApprove(address token, address to, uint256 value) internal { (bool success, bytes memory data) = token.call(abi.encodeWithSelector(IERC20.approve.selector, to, value)); require(success && (data.length == 0 || abi.decode(data, (bool))), "SafeTransferLib/safe-approve-failed"); } } interface GatewayLike { function increaseInvestOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency, uint128 amount) external; function decreaseInvestOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency, uint128 amount) external; function increaseRedeemOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency, uint128 amount) external; function decreaseRedeemOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency, uint128 amount) external; function collectInvest(uint64 poolId, bytes16 trancheId, address investor, uint128 currency) external; function collectRedeem(uint64 poolId, bytes16 trancheId, address investor, uint128 currency) external; function cancelInvestOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency) external; function cancelRedeemOrder(uint64 poolId, bytes16 trancheId, address investor, uint128 currency) external; } interface ERC20Like { function approve(address token, address spender, uint256 value) external; function transferFrom(address from, address to, uint256 amount) external returns (bool); function decimals() external view returns (uint8); function mint(address, uint256) external; function burn(address, uint256) external; } interface LiquidityPoolLike is ERC20Like { function poolId() external returns (uint64); function trancheId() external returns (bytes16); function asset() external view returns (address); function hasMember(address) external returns (bool); function updatePrice(uint128 price) external; function checkTransferRestriction(address from, address to, uint256 value) external view returns (bool); function latestPrice() external view returns (uint128); } interface PoolManagerLike { function currencyIdToAddress(uint128 currencyId) external view returns (address); function currencyAddressToId(address addr) external view returns (uint128); function getTrancheToken(uint64 poolId, bytes16 trancheId) external view returns (address); function getLiquidityPool(uint64 poolId, bytes16 trancheId, address currency) external view returns (address); function isAllowedAsPoolCurrency(uint64 poolId, address currencyAddress) external view returns (bool); } interface EscrowLike { function approve(address token, address spender, uint256 value) external; } interface UserEscrowLike { function transferIn(address token, address source, address destination, uint256 amount) external; function transferOut(address token, address owner, address destination, uint256 amount) external; } struct LPValues { uint128 maxDeposit; uint128 maxMint; uint128 maxWithdraw; uint128 maxRedeem; } contract InvestmentManager is Auth { using MathLib for uint256; using MathLib for uint128; uint8 public constant PRICE_DECIMALS = 18; EscrowLike public immutable escrow; UserEscrowLike public immutable userEscrow; GatewayLike public gateway; PoolManagerLike public poolManager; mapping(address => mapping(address => LPValues)) public orderbook; event File(bytes32 indexed what, address data); event DepositProcessed(address indexed liquidityPool, address indexed user, uint128 indexed currencyAmount); event RedemptionProcessed(address indexed liquidityPool, address indexed user, uint128 indexed trancheTokenAmount); constructor(address escrow_, address userEscrow_) { escrow = EscrowLike(escrow_); userEscrow = UserEscrowLike(userEscrow_); wards[msg.sender] = 1; emit Rely(msg.sender); } modifier onlyGateway() { require(msg.sender == address(gateway), "InvestmentManager/not-the-gateway"); _; } function file(bytes32 what, address data) external auth { if (what == "gateway") gateway = GatewayLike(data); else if (what == "poolManager") poolManager = PoolManagerLike(data); else revert("InvestmentManager/file-unrecognized-param"); emit File(what, data); } function requestDeposit(uint256 currencyAmount, address user) public auth { address liquidityPool = msg.sender; LiquidityPoolLike lPool = LiquidityPoolLike(liquidityPool); address currency = lPool.asset(); uint128 _currencyAmount = _toUint128(currencyAmount); poolManager.isAllowedAsPoolCurrency(lPool.poolId(), currency); _isAllowedToInvest(lPool.poolId(), lPool.trancheId(), currency, user); if (_currencyAmount == 0) { gateway.cancelInvestOrder( lPool.poolId(), lPool.trancheId(), user, poolManager.currencyAddressToId(lPool.asset()) ); return; } SafeTransferLib.safeTransferFrom(currency, user, address(escrow), _currencyAmount); gateway.increaseInvestOrder( lPool.poolId(), lPool.trancheId(), user, poolManager.currencyAddressToId(lPool.asset()), _currencyAmount ); } function requestRedeem(uint256 trancheTokenAmount, address user) public auth { address liquidityPool = msg.sender; LiquidityPoolLike lPool = LiquidityPoolLike(liquidityPool); uint128 _trancheTokenAmount = _toUint128(trancheTokenAmount); poolManager.isAllowedAsPoolCurrency(lPool.poolId(), lPool.asset()); _isAllowedToInvest(lPool.poolId(), lPool.trancheId(), lPool.asset(), user); if (_trancheTokenAmount == 0) { gateway.cancelRedeemOrder( lPool.poolId(), lPool.trancheId(), user, poolManager.currencyAddressToId(lPool.asset()) ); return; } lPool.transferFrom(user, address(escrow), _trancheTokenAmount); gateway.increaseRedeemOrder( lPool.poolId(), lPool.trancheId(), user, poolManager.currencyAddressToId(lPool.asset()), _trancheTokenAmount ); } function decreaseDepositRequest(uint256 _currencyAmount, address user) public auth { uint128 currencyAmount = _toUint128(_currencyAmount); LiquidityPoolLike liquidityPool = LiquidityPoolLike(msg.sender); require(liquidityPool.checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member"); gateway.decreaseInvestOrder( liquidityPool.poolId(), liquidityPool.trancheId(), user, poolManager.currencyAddressToId(liquidityPool.asset()), currencyAmount ); } function decreaseRedeemRequest(uint256 _trancheTokenAmount, address user) public auth { uint128 trancheTokenAmount = _toUint128(_trancheTokenAmount); LiquidityPoolLike liquidityPool = LiquidityPoolLike(msg.sender); require(liquidityPool.checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member"); gateway.decreaseRedeemOrder( liquidityPool.poolId(), liquidityPool.trancheId(), user, poolManager.currencyAddressToId(liquidityPool.asset()), trancheTokenAmount ); } function collectDeposit(address user) public auth { LiquidityPoolLike liquidityPool = LiquidityPoolLike(msg.sender); require(liquidityPool.checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member"); gateway.collectInvest( liquidityPool.poolId(), liquidityPool.trancheId(), user, poolManager.currencyAddressToId(liquidityPool.asset()) ); } function collectRedeem(address user) public auth { LiquidityPoolLike liquidityPool = LiquidityPoolLike(msg.sender); require(liquidityPool.checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member"); gateway.collectRedeem( liquidityPool.poolId(), liquidityPool.trancheId(), user, poolManager.currencyAddressToId(liquidityPool.asset()) ); } function updateTrancheTokenPrice(uint64 poolId, bytes16 trancheId, uint128 currencyId, uint128 price) public onlyGateway { address currency = poolManager.currencyIdToAddress(currencyId); address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, currency); require(liquidityPool != address(0), "InvestmentManager/tranche-does-not-exist"); LiquidityPoolLike(liquidityPool).updatePrice(price); } function handleExecutedCollectInvest( uint64 poolId, bytes16 trancheId, address recipient, uint128 currency, uint128 currencyPayout, uint128 trancheTokensPayout ) public onlyGateway { require(currencyPayout != 0, "InvestmentManager/zero-invest"); address _currency = poolManager.currencyIdToAddress(currency); address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, _currency); require(liquidityPool != address(0), "InvestmentManager/tranche-does-not-exist"); LPValues storage lpValues = orderbook[recipient][liquidityPool]; lpValues.maxDeposit = lpValues.maxDeposit + currencyPayout; lpValues.maxMint = lpValues.maxMint + trancheTokensPayout; LiquidityPoolLike(liquidityPool).mint(address(escrow), trancheTokensPayout); _updateLiquidityPoolPrice(liquidityPool, currencyPayout, trancheTokensPayout); } function handleExecutedCollectRedeem( uint64 poolId, bytes16 trancheId, address recipient, uint128 currency, uint128 currencyPayout, uint128 trancheTokensPayout ) public onlyGateway { require(trancheTokensPayout != 0, "InvestmentManager/zero-redeem"); address _currency = poolManager.currencyIdToAddress(currency); address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, _currency); require(liquidityPool != address(0), "InvestmentManager/tranche-does-not-exist"); LPValues storage lpValues = orderbook[recipient][liquidityPool]; lpValues.maxWithdraw = lpValues.maxWithdraw + currencyPayout; lpValues.maxRedeem = lpValues.maxRedeem + trancheTokensPayout; userEscrow.transferIn(_currency, address(escrow), recipient, currencyPayout); LiquidityPoolLike(liquidityPool).burn(address(escrow), trancheTokensPayout); _updateLiquidityPoolPrice(liquidityPool, currencyPayout, trancheTokensPayout); } function handleExecutedDecreaseInvestOrder( uint64 poolId, bytes16 trancheId, address user, uint128 currency, uint128 currencyPayout ) public onlyGateway { require(currencyPayout != 0, "InvestmentManager/zero-payout"); address _currency = poolManager.currencyIdToAddress(currency); address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, _currency); require(liquidityPool != address(0), "InvestmentManager/tranche-does-not-exist"); require(_currency == LiquidityPoolLike(liquidityPool).asset(), "InvestmentManager/not-tranche-currency"); SafeTransferLib.safeTransferFrom(_currency, address(escrow), user, currencyPayout); } function handleExecutedDecreaseRedeemOrder( uint64 poolId, bytes16 trancheId, address user, uint128 currency, uint128 trancheTokenPayout ) public onlyGateway { require(trancheTokenPayout != 0, "InvestmentManager/zero-payout"); address _currency = poolManager.currencyIdToAddress(currency); address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, _currency); require(address(liquidityPool) != address(0), "InvestmentManager/tranche-does-not-exist"); require( LiquidityPoolLike(liquidityPool).checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member" ); require( LiquidityPoolLike(liquidityPool).transferFrom(address(escrow), user, trancheTokenPayout), "InvestmentManager/trancheTokens-transfer-failed" ); } function totalAssets(uint256 totalSupply, address liquidityPool) public view returns (uint256 _totalAssets) { _totalAssets = convertToAssets(totalSupply, liquidityPool); } function convertToShares(uint256 _assets, address liquidityPool) public view auth returns (uint256 shares) { (uint8 currencyDecimals, uint8 trancheTokenDecimals) = _getPoolDecimals(liquidityPool); uint128 assets = _toUint128(_assets); shares = assets.mulDiv( 10 ** (PRICE_DECIMALS + trancheTokenDecimals - currencyDecimals), LiquidityPoolLike(liquidityPool).latestPrice(), MathLib.Rounding.Down ); } function convertToAssets(uint256 _shares, address liquidityPool) public view auth returns (uint256 assets) { (uint8 currencyDecimals, uint8 trancheTokenDecimals) = _getPoolDecimals(liquidityPool); uint128 shares = _toUint128(_shares); assets = shares.mulDiv( LiquidityPoolLike(liquidityPool).latestPrice(), 10 ** (PRICE_DECIMALS + trancheTokenDecimals - currencyDecimals), MathLib.Rounding.Down ); } function maxDeposit(address user, address liquidityPool) public view returns (uint256 currencyAmount) { currencyAmount = uint256(orderbook[user][liquidityPool].maxDeposit); } function maxMint(address user, address liquidityPool) public view returns (uint256 trancheTokenAmount) { trancheTokenAmount = uint256(orderbook[user][liquidityPool].maxMint); } function maxWithdraw(address user, address liquidityPool) public view returns (uint256 currencyAmount) { currencyAmount = uint256(orderbook[user][liquidityPool].maxWithdraw); } function maxRedeem(address user, address liquidityPool) public view returns (uint256 trancheTokenAmount) { trancheTokenAmount = uint256(orderbook[user][liquidityPool].maxRedeem); } function previewDeposit(address user, address liquidityPool, uint256 _currencyAmount) public view returns (uint256 trancheTokenAmount) { uint128 currencyAmount = _toUint128(_currencyAmount); uint256 depositPrice = calculateDepositPrice(user, liquidityPool); if (depositPrice == 0) return 0; trancheTokenAmount = uint256(_calculateTrancheTokenAmount(currencyAmount, liquidityPool, depositPrice)); } function previewMint(address user, address liquidityPool, uint256 _trancheTokenAmount) public view returns (uint256 currencyAmount) { uint128 trancheTokenAmount = _toUint128(_trancheTokenAmount); uint256 depositPrice = calculateDepositPrice(user, liquidityPool); if (depositPrice == 0) return 0; currencyAmount = uint256(_calculateCurrencyAmount(trancheTokenAmount, liquidityPool, depositPrice)); } function previewWithdraw(address user, address liquidityPool, uint256 _currencyAmount) public view returns (uint256 trancheTokenAmount) { uint128 currencyAmount = _toUint128(_currencyAmount); uint256 redeemPrice = calculateRedeemPrice(user, liquidityPool); if (redeemPrice == 0) return 0; trancheTokenAmount = uint256(_calculateTrancheTokenAmount(currencyAmount, liquidityPool, redeemPrice)); } function previewRedeem(address user, address liquidityPool, uint256 _trancheTokenAmount) public view returns (uint256 currencyAmount) { uint128 trancheTokenAmount = _toUint128(_trancheTokenAmount); uint256 redeemPrice = calculateRedeemPrice(user, liquidityPool); if (redeemPrice == 0) return 0; currencyAmount = uint256(_calculateCurrencyAmount(trancheTokenAmount, liquidityPool, redeemPrice)); } function processDeposit(address user, uint256 currencyAmount) public auth returns (uint256 trancheTokenAmount) { address liquidityPool = msg.sender; uint128 _currencyAmount = _toUint128(currencyAmount); require( (_currencyAmount <= orderbook[user][liquidityPool].maxDeposit && _currencyAmount != 0), "InvestmentManager/amount-exceeds-deposit-limits" ); uint256 depositPrice = calculateDepositPrice(user, liquidityPool); require(depositPrice != 0, "LiquidityPool/deposit-token-price-0"); uint128 _trancheTokenAmount = _calculateTrancheTokenAmount(_currencyAmount, liquidityPool, depositPrice); _deposit(_trancheTokenAmount, _currencyAmount, liquidityPool, user); trancheTokenAmount = uint256(_trancheTokenAmount); } function processMint(address user, uint256 trancheTokenAmount) public auth returns (uint256 currencyAmount) { address liquidityPool = msg.sender; uint128 _trancheTokenAmount = _toUint128(trancheTokenAmount); require( (_trancheTokenAmount <= orderbook[user][liquidityPool].maxMint && _trancheTokenAmount != 0), "InvestmentManager/amount-exceeds-mint-limits" ); uint256 depositPrice = calculateDepositPrice(user, liquidityPool); require(depositPrice != 0, "LiquidityPool/deposit-token-price-0"); uint128 _currencyAmount = _calculateCurrencyAmount(_trancheTokenAmount, liquidityPool, depositPrice); _deposit(_trancheTokenAmount, _currencyAmount, liquidityPool, user); currencyAmount = uint256(_currencyAmount); } function _deposit(uint128 trancheTokenAmount, uint128 currencyAmount, address liquidityPool, address user) internal { LiquidityPoolLike lPool = LiquidityPoolLike(liquidityPool); _decreaseDepositLimits(user, liquidityPool, currencyAmount, trancheTokenAmount); require(lPool.checkTransferRestriction(msg.sender, user, 0), "InvestmentManager/trancheTokens-not-a-member"); require( lPool.transferFrom(address(escrow), user, trancheTokenAmount), "InvestmentManager/trancheTokens-transfer-failed" ); emit DepositProcessed(liquidityPool, user, currencyAmount); } function processRedeem(uint256 trancheTokenAmount, address receiver, address user) public auth returns (uint256 currencyAmount) { address liquidityPool = msg.sender; uint128 _trancheTokenAmount = _toUint128(trancheTokenAmount); require( (_trancheTokenAmount <= orderbook[user][liquidityPool].maxRedeem && _trancheTokenAmount != 0), "InvestmentManager/amount-exceeds-redeem-limits" ); uint256 redeemPrice = calculateRedeemPrice(user, liquidityPool); require(redeemPrice != 0, "LiquidityPool/redeem-token-price-0"); uint128 _currencyAmount = _calculateCurrencyAmount(_trancheTokenAmount, liquidityPool, redeemPrice); _redeem(_trancheTokenAmount, _currencyAmount, liquidityPool, receiver, user); currencyAmount = uint256(_currencyAmount); } function processWithdraw(uint256 currencyAmount, address receiver, address user) public auth returns (uint256 trancheTokenAmount) { address liquidityPool = msg.sender; uint128 _currencyAmount = _toUint128(currencyAmount); require( (_currencyAmount <= orderbook[user][liquidityPool].maxWithdraw && _currencyAmount != 0), "InvestmentManager/amount-exceeds-withdraw-limits" ); uint256 redeemPrice = calculateRedeemPrice(user, liquidityPool); require(redeemPrice != 0, "LiquidityPool/redeem-token-price-0"); uint128 _trancheTokenAmount = _calculateTrancheTokenAmount(_currencyAmount, liquidityPool, redeemPrice); _redeem(_trancheTokenAmount, _currencyAmount, liquidityPool, receiver, user); trancheTokenAmount = uint256(_trancheTokenAmount); } function _redeem( uint128 trancheTokenAmount, uint128 currencyAmount, address liquidityPool, address receiver, address user ) internal { LiquidityPoolLike lPool = LiquidityPoolLike(liquidityPool); _decreaseRedemptionLimits(user, liquidityPool, currencyAmount, trancheTokenAmount); userEscrow.transferOut(lPool.asset(), user, receiver, currencyAmount); emit RedemptionProcessed(liquidityPool, user, trancheTokenAmount); } function calculateDepositPrice(address user, address liquidityPool) public view returns (uint256 depositPrice) { LPValues storage lpValues = orderbook[user][liquidityPool]; if (lpValues.maxMint == 0) { return 0; } depositPrice = _calculatePrice(lpValues.maxDeposit, lpValues.maxMint, liquidityPool); } function calculateRedeemPrice(address user, address liquidityPool) public view returns (uint256 redeemPrice) { LPValues storage lpValues = orderbook[user][liquidityPool]; if (lpValues.maxRedeem == 0) { return 0; } redeemPrice = _calculatePrice(lpValues.maxWithdraw, lpValues.maxRedeem, liquidityPool); } function _calculatePrice(uint128 currencyAmount, uint128 trancheTokenAmount, address liquidityPool) public view returns (uint256 depositPrice) { (uint8 currencyDecimals, uint8 trancheTokenDecimals) = _getPoolDecimals(liquidityPool); uint256 currencyAmountInPriceDecimals = _toPriceDecimals(currencyAmount, currencyDecimals, liquidityPool); uint256 trancheTokenAmountInPriceDecimals = _toPriceDecimals(trancheTokenAmount, trancheTokenDecimals, liquidityPool); depositPrice = currencyAmountInPriceDecimals.mulDiv( 10 ** PRICE_DECIMALS, trancheTokenAmountInPriceDecimals, MathLib.Rounding.Down ); } function _updateLiquidityPoolPrice(address liquidityPool, uint128 currencyPayout, uint128 trancheTokensPayout) internal { uint128 price = _toUint128(_calculatePrice(currencyPayout, trancheTokensPayout, liquidityPool)); LiquidityPoolLike(liquidityPool).updatePrice(price); } function _calculateTrancheTokenAmount(uint128 currencyAmount, address liquidityPool, uint256 price) internal view returns (uint128 trancheTokenAmount) { (uint8 currencyDecimals, uint8 trancheTokenDecimals) = _getPoolDecimals(liquidityPool); uint256 currencyAmountInPriceDecimals = _toPriceDecimals(currencyAmount, currencyDecimals, liquidityPool).mulDiv( 10 ** PRICE_DECIMALS, price, MathLib.Rounding.Down ); trancheTokenAmount = _fromPriceDecimals(currencyAmountInPriceDecimals, trancheTokenDecimals, liquidityPool); } function _calculateCurrencyAmount(uint128 trancheTokenAmount, address liquidityPool, uint256 price) internal view returns (uint128 currencyAmount) { (uint8 currencyDecimals, uint8 trancheTokenDecimals) = _getPoolDecimals(liquidityPool); uint256 currencyAmountInPriceDecimals = _toPriceDecimals( trancheTokenAmount, trancheTokenDecimals, liquidityPool ).mulDiv(price, 10 ** PRICE_DECIMALS, MathLib.Rounding.Down); currencyAmount = _fromPriceDecimals(currencyAmountInPriceDecimals, currencyDecimals, liquidityPool); } function _decreaseDepositLimits(address user, address liquidityPool, uint128 _currency, uint128 trancheTokens) internal { LPValues storage lpValues = orderbook[user][liquidityPool]; if (lpValues.maxDeposit < _currency) { lpValues.maxDeposit = 0; } else { lpValues.maxDeposit = lpValues.maxDeposit - _currency; } if (lpValues.maxMint < trancheTokens) { lpValues.maxMint = 0; } else { lpValues.maxMint = lpValues.maxMint - trancheTokens; } } function _decreaseRedemptionLimits(address user, address liquidityPool, uint128 _currency, uint128 trancheTokens) internal { LPValues storage lpValues = orderbook[user][liquidityPool]; if (lpValues.maxWithdraw < _currency) { lpValues.maxWithdraw = 0; } else { lpValues.maxWithdraw = lpValues.maxWithdraw - _currency; } if (lpValues.maxRedeem < trancheTokens) { lpValues.maxRedeem = 0; } else { lpValues.maxRedeem = lpValues.maxRedeem - trancheTokens; } } function _isAllowedToInvest(uint64 poolId, bytes16 trancheId, address currency, address user) internal returns (bool) { address liquidityPool = poolManager.getLiquidityPool(poolId, trancheId, currency); require(liquidityPool != address(0), "InvestmentManager/unknown-liquidity-pool"); require( LiquidityPoolLike(liquidityPool).checkTransferRestriction(address(0), user, 0), "InvestmentManager/not-a-member" ); return true; } function _toUint128(uint256 _value) internal pure returns (uint128 value) { if (_value > type(uint128).max) { revert("InvestmentManager/uint128-overflow"); } else { value = uint128(_value); } } function _toPriceDecimals(uint128 _value, uint8 decimals, address liquidityPool) internal view returns (uint256 value) { if (PRICE_DECIMALS == decimals) return uint256(_value); value = uint256(_value) * 10 ** (PRICE_DECIMALS - decimals); } function _fromPriceDecimals(uint256 _value, uint8 decimals, address liquidityPool) internal view returns (uint128 value) { if (PRICE_DECIMALS == decimals) return _toUint128(_value); value = _toUint128(_value / 10 ** (PRICE_DECIMALS - decimals)); } function _getPoolDecimals(address liquidityPool) internal view returns (uint8 currencyDecimals, uint8 trancheTokenDecimals) { currencyDecimals = ERC20Like(LiquidityPoolLike(liquidityPool).asset()).decimals(); trancheTokenDecimals = LiquidityPoolLike(liquidityPool).decimals(); } }

